VOWELS = frozenset("aeiou")

def count_letters(s: str) -> tuple[int, int]:
    vowels = consonants = 0
    for ch in s.lower():
        if not ch.isalpha():
            continue
        if ch in VOWELS:
            vowels += 1
        else:
            consonants += 1
    return vowels, consonants

assert count_letters("Hello, World!") == (3, 7)
assert count_letters("") == (0, 0)
assert count_letters("AEIOU xyz 123") == (5, 3)

